#!/usr/bin/env bash
# 《夜巡》第三章素材批量生成：逐张调用 codex-pool，失败记录不中断
cd ~/workspace/yexun || exit 1
POOL=~/workspace/codex-pet/codex-pool.sh
LOG=~/workspace/yexun/art/ch3_work/gen_batch.log
STYLE='SP style of the game Yexun: hand-painted 2D, soft brushwork between watercolor wash and thin gouache, low-saturation grey-blue / mist-teal / faded wood palette, dim red only as tiny accents, dreamy soft glow, night in muted blue-grey never pure black. Absolutely NO readable text, characters or calligraphy anywhere, NO watermark.'
SPRITE='Isolated single subject on a fully transparent background (true alpha PNG), nothing else in frame.'

gen() {
  local out="$1" anchor="$2" prompt="$3"
  if [ -f "art/$out" ]; then echo "SKIP $out (exists)" >> "$LOG"; return; fi
  echo "=== $(date '+%T') START $out ===" >> "$LOG"
  printf '%s' "$prompt" | "$POOL" -i "$anchor" >> "$LOG" 2>&1
  if [ -f "art/$out" ]; then echo "OK $out" >> "$LOG"; else echo "FAIL $out" >> "$LOG"; fi
}

# ---- 灵域版底板：以现实域为编辑底图，只改色调雾光、构图不动 ----
gen bg_hall_spirit.png ~/workspace/yexun/art/bg_hall_realm.png "Edit the attached image into the SPIRIT-REALM version of the same game background plate, save as art/bg_hall_spirit.png. Keep the composition, architecture and every object position EXACTLY the same. Change only the atmosphere: overall one step colder and darker (deep mist-teal and blue-grey), much heavier fog, ALL warm light extinguished (lanterns dark, no candle glow), damp stone reflections turned cold and faint, an eerie stillness. Do NOT add any glowing spirit cores or light orbs. $STYLE"

# ---- 后殿杂物间底板 ----
gen bg_store_realm.png ~/workspace/yexun/concept/concept_07_ancestralhall_ch3_SP.png "Use the image_gen tool to generate one game background plate and save it as art/bg_store_realm.png in the current workspace. Style anchor: the attached concept image ($STYLE). Scene: an EMPTY dim storeroom stage plate for a 2D game, wide landscape composition — the back-hall storage room of a temple. Left edge: half of a covered corridor opening (dark wooden pillars, a hanging hook on the wall by the door, the floor strip where a paper horse would stand — left empty). Centre and right: a cluttered old storage room in near-darkness — stacks of old bamboo ware silhouettes against the wall, piles of dusty covered shapes under faded cloth, a small old shrine niche at the back wall with an EMPTY burner stand (no burner on it), one thin shaft of cold moonlight from a high small window, cobwebs, dust. The floor space in the middle stays clear. NO people, NO paper palanquin, NO wooden chest in the centre, NO readable text anywhere. Oppressive, quiet, forgotten for decades."

gen bg_store_spirit.png ~/workspace/yexun/art/bg_store_realm.png "Edit the attached image into the SPIRIT-REALM version of the same game background plate, save as art/bg_store_spirit.png. Keep the composition and every object position EXACTLY the same. Change only the atmosphere: overall one step colder and darker (deep mist-teal and blue-grey), heavier fog and dust hanging in the air, the moonlight shaft turned colder and dimmer, all remaining warmth gone, an eerie stillness. Do NOT add any glowing spirit cores or light orbs. $STYLE"

# ---- 物件精灵 8 件 ----
gen obj_altar.png ~/workspace/yexun/concept/concept_07_ancestralhall_ch3_SP.png "Use the image_gen tool to generate one game object sprite and save it as art/obj_altar.png in the current workspace. $SPRITE $STYLE Subject: a Chaoshan ancestral-hall ALTAR TABLE (xiang'an), side-front view: a long dark-wood altar table with floral painted panels, on it a squat bronze incense burner in the centre with three incense sticks — the middle one tall and lit with a tiny ember tip and a thin wisp of smoke — flanked by a pair of brass candle stands with small flames and two small offering plates. Solemn, damp night mood. No people."

gen obj_register.png ~/workspace/yexun/concept/concept_07_ancestralhall_ch3_SP.png "Use the image_gen tool to generate one game object sprite and save it as art/obj_register.png in the current workspace. $SPRITE $STYLE Subject: a clan REGISTER CABINET with its register books, side-front view: a waist-high dark-wood cabinet with one door swung open, inside it stacks of thick thread-bound old registers with faded cloth covers; on top of the cabinet one register lies OPEN — its pages show only unreadable smudged brush-stroke blocks (abstract ink marks, NOT real characters), and the open spread has a clearly visible TORN-PAGE GAP: a row of neat torn paper stubs along the binding where one whole page was ripped out, the stub edge slightly damp-stained. This torn gap must be clearly readable visually. No people, no legible writing anywhere."

gen obj_bell.png ~/workspace/yexun/concept/concept_07_ancestralhall_ch3_SP.png "Use the image_gen tool to generate one game object sprite and save it as art/obj_bell.png in the current workspace. $SPRITE $STYLE Subject: a large ancestral-hall BRONZE BELL hanging in its wooden frame, side view: an aged green-patina bronze bell with abstract raised dot-and-swirl patterns (NO inscriptions, NO characters), hanging by a loop from a dark carved wooden beam frame with two posts, a horizontal striking beam resting beside it. Heavy, solemn, slightly damp sheen. No people."

gen obj_teatable.png ~/workspace/yexun/concept/concept_07_ancestralhall_ch3_SP.png "Use the image_gen tool to generate one game object sprite and save it as art/obj_teatable.png in the current workspace. $SPRITE $STYLE Subject: a Chaoshan GONGFU TEA TABLE set, side-front view: a low dark-wood tea table holding a rectangular tea tray; on the tray a small reddish-brown clay teapot, a fairness pitcher, and THREE tiny white porcelain tasting cups in a row; a small kettle at the side; faint steam rising from the teapot spout. Refined, calm, lamplit warmth kept very dim and desaturated. No people, no text."

gen obj_sedan_wreck.png ~/workspace/yexun/art/obj_sedan_small.png "Use the image_gen tool to generate one game object sprite and save it as art/obj_sedan_wreck.png in the current workspace. $SPRITE $STYLE Subject: the WRECKED REMAINS of a small plain-white paper palanquin — the broken leftover of the intact paper sedan in the attached reference image, and it must look clearly DIFFERENT from it: the paper body collapsed and torn, one side caved in, bamboo frame ribs exposed and snapped, carrying poles gone, the whole wreck leaning against nothing on the floor; draped half over it a faded cloth panel (a memorial-tablet cloth) whose surface is BLANK and water-stained, covering part of the inner lining. Decades old, dusty, water-damaged, mournful. NOT a usable sedan. No people, no text."

gen obj_bamboo.png ~/workspace/yexun/concept/concept_07_ancestralhall_ch3_SP.png "Use the image_gen tool to generate one game object sprite and save it as art/obj_bamboo.png in the current workspace. $SPRITE $STYLE Subject: a pile of OLD BAMBOO WARE in a storeroom corner, side view: a leaning bundle of long bamboo poles tied with frayed rope, two woven bamboo baskets (one overturned), loose bamboo strips and a short section of old bamboo ladder, all greyed, dusty and slightly mildewed with age. Quiet, forgotten feel. No people, no text."

gen obj_chest.png ~/workspace/yexun/concept/concept_07_ancestralhall_ch3_SP.png "Use the image_gen tool to generate one game object sprite and save it as art/obj_chest.png in the current workspace. $SPRITE $STYLE Subject: an OLD WOODEN STORAGE CHEST, side-front view: a big dark-wood chest with iron corner fittings and a heavy iron latch, its lid opened just a crack with darkness inside, dust thick on the top edge, wood grain faded and water-stained near the bottom. Heavy, sealed-for-decades feel. No people, no text, no markings."

gen obj_incense_old.png ~/workspace/yexun/art/obj_incense_small.png "Use the image_gen tool to generate one game object sprite and save it as art/obj_incense_old.png in the current workspace. $SPRITE $STYLE Subject: an OLD BACK-HALL INCENSE BURNER — clearly different from the attached reference (that one is a small neat stone burner): this one is a squat aged BRONZE burner, round-bellied with two small ear handles, one visible fine crack down its side, filled with cold grey ash, NO incense sticks, only the faintest dying ember glow deep in the ash. Dusty, long-neglected, decades without a proper fire. No people, no text."

# ---- 角色精灵 5 人 ----
CHARBASE='Full-body side-view standing pose facing right, one single person, isolated on a fully transparent background (true alpha PNG).'
gen char_liushu.png ~/workspace/yexun/concept/concept_11_characters_liushu_shuisheng_SP.png "Use the image_gen tool to generate one game character sprite and save it as art/char_liushu.png in the current workspace. $CHARBASE $STYLE Character: LIUSHU GONG, the elderly clan-hall steward from the attached reference (the old man on the left) — keep his face, grey-white topknot bun, thin moustache and beard, and his long dark-indigo patterned robe with frog buttons and a dim red sash. Standing dignified and upright, one hand holding a small brown clay teapot at waist height in a tea-hosting pose, expression calm, courteous and completely unreadable. A soft wall of politeness, not a villain face."

gen char_shuisheng.png ~/workspace/yexun/concept/concept_11_characters_liushu_shuisheng_SP.png "Use the image_gen tool to generate one game character sprite and save it as art/char_shuisheng.png in the current workspace. $CHARBASE $STYLE Character: SHUISHENG, a 24-year-old temple odd-job man, based on the young man in the attached reference but clearly an adult of 24 — messy black hair, patched shabby grey-brown work clothes with rolled sleeves and trouser cuffs, cloth shoes. He hugs a heavy coil of thick hemp rope against his chest with both arms, shoulders slightly hunched, head lowered and eyes glancing aside — guilt and nervousness carried in the posture and gaze only, his face is ordinary and tired, NOT sinister, NOT a villain."

gen char_keeper.png ~/workspace/yexun/concept/concept_07_ancestralhall_ch3_SP.png "Use the image_gen tool to generate one game character sprite and save it as art/char_keeper.png in the current workspace. $CHARBASE $STYLE Character: the old REGISTER KEEPER of the clan hall — a very old, thin, slightly stooped man in his eighties, sparse grey hair in a small knot, plain faded grey-blue robe worn threadbare, one arm cradling a thick thread-bound register book against his side, the other hand holding a ring of old iron keys. Weary, evasive eyes looking away; a man who has kept other people's secrets too long. Ordinary and pitiable, not sinister."

gen char_member_a.png ~/workspace/yexun/concept/concept_05_characters_SP.png "Use the image_gen tool to generate one game character sprite and save it as art/char_member_a.png in the current workspace. $CHARBASE $STYLE Character: a Yingge dance-troupe member in his forties — stocky build, weathered face, dark short work jacket with sleeves rolled up, a worn towel draped over one shoulder, dim red waist sash like the other troupe members. Standing in a waiting, impatient posture, weight on one leg, glancing off to the side as if wanting to leave. An ordinary working man tired of waiting around at midnight."

gen char_member_b.png ~/workspace/yexun/concept/concept_05_characters_SP.png "Use the image_gen tool to generate one game character sprite and save it as art/char_member_b.png in the current workspace. $CHARBASE $STYLE Character: a young Yingge dance-troupe member in his early twenties — lean build, short black hair, dark short work jacket over a plain undershirt, dim red waist sash, holding a pair of short Yingge dance sticks loosely down at his sides. Standing restless and upright, looking into the distance with a hint of longing, as if already thinking about leaving for the city next year. Ordinary village youth, not a hero pose."

echo "=== BATCH DONE $(date '+%T') ===" >> "$LOG"
